RELAY_HOLD_SEC = 300
# ★★Claude CLI のセッション上限だけは「再配達の回数を消費しない」(2026-08-14)。
#   発注= 研究室HQ DISPATCH-aegis-gl-1786643264450。実測 2026-08-14 01:04〜02:44 JST:
#   `You've hit your session limit · resets 2:40am (Etc/GMT-9)` で 21件 / 5部門が rc=1・2秒で
#   即死し、**Chamiの便(msg 1537508993923154042)が deliveries=6 で dead へ落ちた**。
#   deadは二度と拾われない=黙って消える=最悪の事故。
#   原因は判定の粗さ= 「相手が一時的に受けられない」と「この便自体が毒」を同じカウンタで
#   数えていた。上限は数十分で明ける外部要因なので、**回数を数えず、明ける時刻まで寝る**。
#   ★上限エラーは復帰時刻を本文で教えてくれる(`resets 2:40am`)ので、それをそのまま使う。
#     読めなければ既定の待ち(RELAY_LIMIT_FALLBACK_SEC)へ倒す=判定不能でも便は死なせない。
RELAY_LIMIT_FALLBACK_SEC = 900
RE_SESSION_LIMIT = re.compile(r"session limit|usage limit|rate limit|resets\s+\d", re.I)
RE_LIMIT_RESET = re.compile(r"resets?\s+(\d{1,2})(?::(\d{2}))?\s*(am|pm)?", re.I)


def session_limit_retry_after(why, now=None):
    """上限エラーなら「いつ再開してよいか」のエポック秒を返す。上限でなければ None。

    `why` は session_relay.LAST_ERROR の文字列(例:
      `Claude CLIがエラーを返した(rc=1): You've hit your session limit · resets 2:40am (Etc/GMT-9)`)。
    ★時刻の解釈= このPCのローカル時刻(JST)として読む。CLIが併記する `Etc/GMT-9` は
      POSIX式の符号反転で **UTC+9=JST** であり、ローカルと一致する(2026-08-14 実測)。
    ★過ぎている時刻(例 02:40 を 03:00 に読んだ)は**翌日ではなく直後**とみなす=
      既に明けているのに1日寝る、という最悪の取り違えをしない。
    ★1分だけ余裕を足す(境界ちょうどに叩いてもう1回弾かれるのを避ける)。
    """
    if not why or not RE_SESSION_LIMIT.search(why):
        return None
    now = now or time.time()
    m = RE_LIMIT_RESET.search(why)
    if not m:
        return now + RELAY_LIMIT_FALLBACK_SEC
    hh, mm, ap = int(m.group(1)), int(m.group(2) or 0), (m.group(3) or "").lower()
    if ap == "pm" and hh != 12:
        hh += 12
    elif ap == "am" and hh == 12:
        hh = 0
    if hh > 23 or mm > 59:
        return now + RELAY_LIMIT_FALLBACK_SEC
    t = time.localtime(now)
    target = time.mktime((t.tm_year, t.tm_mon, t.tm_mday, hh, mm, 0, 0, 0, -1))
    if target <= now:
        # 既に過ぎている= もう明けている(または直後)。長く寝かせない。
        return now + 60
    return min(target + 60, now + 6 * 3600)   # 誤読で半日寝ないための天井
# ★★受信側の集約窓(coalesce・2026-08-08 イージス研究室 / 発注= 研究室HQ 8/4 07:29)。
#   何のためか= Chamiが推敲を**小分けに連投**する部屋で、断片1つごとに走って断片1つごとに
#   返すと、①話が途中の状態で3回も4回も応答が返る ②同じ推敲に何度もモデルを回す。
#   → **連投が落ち着いてから、溜まった分を全部込みで1回返す。**
#   ★効かせるのは `coalesce_sec` を持つ部門だけ(既定=無し=他29室は1ミリも変わらない。C-035)。
#   ★安全の核= 待つ間、便は**claimしない**(queueに残したまま覗くだけ)。掴んで抱えないので
#     デーモンが落ちても喪失しない・deliveriesも減らない=ドレインの窓を作らない(INC-100型を避ける)。
COALESCE_MAX_SEC = 300         # 連投が止まらなくても、最初の便からこの秒数で必ず走る(待ち続けない)
COALESCE_MAX_ITEMS = 8         # 1回に束ねる上限(超えた分は次の巡回でまた束ねる)
COALESCE_PEEK_MAX = 20         # 覗く行数の上限
WORK_MODEL = "sonnet"          # ★O3(裁-3): 作業agentの既定(実装の物量=sonnet・分業表準拠)
# ★部門ごとのモデル上書き(2026-07-21 Chami指摘「デーモンの処理能力が悪かったら、
#   作業してもらっても結局バグを作る温床。**一番重視してるのは品質を落とさないこと**」)。
#   指摘は正しい。既定のsonnetは `CLAUDE.md §5.1` の分業表で「見た目・文言の調整/単一ファイルの
#   素直な追加」に割り当てられた層であって、**判断が要る部屋には足りない**。
#   同 §1 の優先順位は **正確性>安全性>検証可能性>保守性>トークン効率>速度** で、
#   「品質を犠牲にしたトークン節約は禁止」と明記されている=**判断の部屋は上位モデルにするのが規約側の答え**。
#   DEPT_CONF に "work_model" があればそれを使う。無ければ従来どおり WORK_MODEL。
def work_model_for(conf):
    m = (conf or {}).get("work_model") or WORK_MODEL
    # ★素の "opus" は明示版へ固定(2026-07-31 Chami指示)。CLIが最新へ張り替えても Opus 5 等へ
    #   黙って乗り換わらせない=単価跳ねの防止。品質の床= Opus 4.8世代。戻すなら下1行を消す。
    return "claude-opus-4-8" if (m or "").strip() == "opus" else m

# ★部門ごとの reasoning effort 上書き(2026-08-08・人事REQ-hr-room-8dc9faa2f1=Chami「測っといて。
#   適切なやつに/状況で可変できる方が確実ならそれで」)。人事の実測=同一パズルで正解は不変、
#   出力トークンだけがエフォートで動いた(low=278/medium=445/既定=617/high=754/xhigh=3043)。
#   `claude --print --effort <level>` が low/medium/high/xhigh/max を受けるのを実測確認済。
#   ★opt-in設計: DEPT_CONF に "work_effort" がある部屋だけ渡す。無ければフラグを付けず CLI 既定
#     (617相当)=従来の全部屋の挙動を変えない(名指し1箇所を全体へ広げない=C-035)。
#   ★不正値は無視して既定へ倒す(fail-safe=判定不能なら品質側=既定へ)。品質>トークン効率(§1)。
_VALID_EFFORT = ("low", "medium", "high", "xhigh", "max")
def work_effort_for(conf):
    e = ((conf or {}).get("work_effort") or "").strip().lower()
    return e if e in _VALID_EFFORT else None
# ★O3(裁-3・改善書P1-5): 作業agentの許可ツールを最小allowlistへ固定。旧 bypassPermissions は
#   「何でも実行可」=プロンプトインジェクション耐性が最弱線だった。--print(headless)では未許可
#   ツールは自動拒否(プロンプトを出せないため)=allowlist外は安全に落ちる。ファイル作業+検証に
#   必要な範囲だけ許可。Bashのコマンド単位のさらなる絞り込みはO5の follow-up。
WORK_ALLOWED_TOOLS = ["Read", "Edit", "Write", "Grep", "Glob", "Bash"]
# 作業依頼キーワード(=main箱回送 or work_scope部門でのwork_generate起動の判定に使う)。
# ★依頼形(〜して/〜お願い等)に限定する(2026-07-20 qa-reviewer点検・過剰回送修正=INC本文参照)。
#   旧版は「反映」「実装」「修正」「デプロイ」等を裸の名詞で拾っており、"反映完了したら知らせて"
#   のような単なる報告依頼(情報要求)にも一致→研究室への過剰回送(実測 hq 8件+hr-context 5件)の主因だった。
#   バグ/エラー/壊れ は完了報告パターン(「〜したら知らせて」)と結びつかない症状語のため対象外
#   (system-engineerの通常のバグ報告受理を壊さないよう保守的に現状維持)。
WORK_WORDS = ("直して", "直しといて", "修正して", "修正お願い", "実装して", "実装お願い",
              "追加して", "デプロイして", "デプロイお願い", "変えて", "作って", "調べて",
              "特定して", "バグ", "エラー", "壊れ", "対応して", "やって",
              "反映して", "反映お願い", "反映をお願い", "消して", "削除して", "削除お願い")
# 情報要求語(教えて/知らせて/確認して 等)。WORK_WORDSはこれらとは重複しない設計
# (=情報要求のみの文はWORK_WORDSに一致せず自動的にis_work=Falseになる)。
# テスト(test_dept_daemon_classify.py)で非重複と分類結果を検証する。
INFO_WORDS = ("教えて", "教えてほしい", "知らせて", "確認して", "見てほしい", "見せて")


def classify_work(content):
    """本文が「作業依頼」かどうかを判定する(main箱回送/work_scope起動の判定に使用)。

    単純なWORK_WORDS部分一致だが、判定ロジックを1箇所に集約することで
    generate()とhandle()の重複判定がズレる事故を防ぐ(2026-07-20)。

    ★これは**速い一次判定**でしかない。自然文(「設計して手足として動かして」)は
      原理的に取りこぼす。取りこぼしの回収は WORK_MARKER(キャラ自身の申告)が担う。
      **キーワードを増やして精度を上げようとしないこと**(自然文である限り必ず再発する。
      2026-07-20に実際に事故った)。
    """
    return any(w in str(content) for w in WORK_WORDS)


def is_conversation_only(conf):
    """この部屋が「会話専用(回送しない・作業判定しない)」か(2026-07-22 Chami指示)。

    判定を1箇所に集約しておく(generate/handleでズレると、片方だけ回送が残る事故になる)。
    ★キーが無い部屋は必ず False=従来動作。例外も False へ倒す(fail-safe)。
    """
    try:
        return bool((conf or {}).get("conversation_only"))
    except Exception:
        return False


def _failopen_flag_path():
    """実効フラグファイルの在りか。RELAY_FAILOPEN_FLAG で上書き可(テスト用)。既定= local/queue/relay_failopen.flag。"""
    p = os.environ.get("RELAY_FAILOPEN_FLAG", "").strip()
    if p:
        return p
    root = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
    return os.path.join(root, "local", "queue", "relay_failopen.flag")


def _failopen_flagfile():
    """フラグファイル(あれば)から (enable, depts) を読む。★envは長寿命keeper起動時のブロックに凍結され
    worker再起動でも解けない(実測 2026-08-02: keeper/worker とも 02:49 起動→06:42 の setx を拾えない)。
    実効の kill-switch/カナリアは **毎便読み直すこのファイル** で持つ=プロセス再起動なしに実行時ON/OFF。
    ファイルが無い/空/壊れ= None を返し env へフォールバック(=沈黙対策が既存配送を巻き込まない fail-safe)。
    """
    try:
        p = _failopen_flag_path()
        if not os.path.exists(p):
            return None
        with open(p, "r", encoding="utf-8") as fh:
            raw = fh.read().strip()
        if not raw:
            return None
        obj = json.loads(raw)
        depts = [str(d).strip() for d in (obj.get("depts") or []) if str(d).strip()]
        return (bool(obj.get("enable")), depts)
    except Exception:
        return None


def failopen_enabled(dept, rec):
    """relay無人時 fail-open(§3.1)を、この便で発火してよいか。(2026-08-02 イージス研究室)

    HQ裁定 msg=1533226514794025081 の封筒条件のうち **kill-switch とカナリア** をここに集約する。
      1 kill-switch: 明示 env(off/false/no/0)は最優先のハードkill=必ず False。実効の停止は
        **フラグファイルを消す**こと(ワンコマンド `rm local/queue/relay_failopen.flag` で即・現行挙動へ)。
      2 カナリア: 有効化しても **いきなり全19部門へは入れない**。test:true の検証便か、
        allowlist(env RELAY_FAILOPEN_DEPTS / フラグファイルの depts)に挙げた部門だけ発火。`*`/`all` で全部門。
    ★env はプロセス起動時に凍結されるため、走っている精霊への実効操作はフラグファイル側で行う。
    ★判定不能・例外は False(fail-safe=沈黙対策の追加機構が、既存の配送を巻き込まない)。
    """
    try:
        env_flag = os.environ.get("RELAY_FAILOPEN", "").strip().lower()
        if env_flag in ("0", "off", "false", "no"):
            return False  # 明示 env での停止は最優先(ハードkill)
        env_on = env_flag != ""
        env_depts = [d.strip() for d in os.environ.get("RELAY_FAILOPEN_DEPTS", "").split(",")
                     if d.strip()]

        ff = _failopen_flagfile()
        file_on, file_depts = ff if ff is not None else (False, [])

        if not (env_on or file_on):
            return False
        if isinstance(rec, dict) and rec.get("test"):
            return True
        allow = env_depts + file_depts
        if "*" in allow or "all" in allow:
            return True
        return dept in allow
    except Exception:
        return False


def failopen_inject(rec):
    """fail-open を**安全に1回通す**ための注入点(2026-08-08 イージス研究室)。

    なぜ要るか= fail-open の発火条件は `_relay_ok=False`(=部屋の永続セッションが返せない)だけ。
      これを自然に待つと**生きた部屋が事故を起こすまで一生確認できない**(実測= 2026-08-02 06:53に
      armedしてから 8/8 まで6日間、発火ログ0件)。かといって確認のために生きた消費者を殺すのは
      **事故の自作**で、§3「本番の部屋でテストしない」に反する。
      → 消費者には一切触れず、**この便に限って relay を呼ばずに「失敗した」ことにする**。

    安全性= 門が2枚ある。**両方**満たさないと絶対に True にならない。
      1 `test: true`= 検証便であること。本番便には付かない(付ければ**送信そのものが止まる**=
        既存の実弾検証と同じ守り・行4552)。
      2 `relay_fail_inject: true`= この検証のための明示の合図。既定の便には存在しないキー。
    ★片方だけでは効かない=本番の配送は1バイトも変わらない。★例外は False(fail-safe)。
    """
    try:
        if not isinstance(rec, dict):
            return False
        if not rec.get("test"):
            return False            # 本番便では絶対に発火しない(1枚目の門)
        return bool(rec.get("relay_fail_inject"))
    except Exception:
        return False


# ★恒久対処(2026-07-20 組織層GL室): 「回します/やっておく」と言って何も起きない事故の真因は
#   **返信を書く判断者(キャラLLM)と、回送/作業を起こす判断者(キーワード正規表現)が別人**だったこと。
#   キャラが約束してもコードは約束を知らないので裏切りが構造的に発生する。
#   対処= キャラ自身に「これは作業依頼か」を申告させ、**同じ判断者から返信と発火を出す**。
#   申告は返信末尾の1行マーカーで受け取り、Discordへ送る前に機械的に取り除く。
WORK_MARKER = "<<WORK>>"


def split_work_marker(reply):
    """返信本文から WORK_MARKER を取り除き (本文, キャラの申告) を返す。

    マーカーは行内のどこにあっても拾う(LLMが「 <<WORK>>」等と揺らしても落とさない)。
    マーカーだけの行は丸ごと落とし、本文中に混ざった場合はその語だけ除去する。
    """
    text = str(reply or "")
    if WORK_MARKER not in text:
        return text.strip(), False
    kept = []
    for line in text.splitlines():
        if WORK_MARKER in line:
            rest = line.replace(WORK_MARKER, "").strip()
            if rest:
                kept.append(rest)
        else:
            kept.append(line)
    return "\n".join(kept).strip(), True


# ★作業継続のマーカー(2026-07-29 Chami指示で**札を廃止**して置き換えたもの)。
#   Chami原文=「**うーん、最後の状態:完了とかやめて欲しいなあ、文脈でわかるようにして欲しいってこと。**」
#   経緯= 「実装が完了したのかどうかわからない」への最初の答えは `状態: 完了/作業中/待ち` の
#     **札を貼らせること**だった。だがChamiが欲しいのは**読めば分かる文章**であって機械的なラベルではない。
#     → 本文は札なし(普通の言葉で「〜まで終わった」「〜が残っている」と書く)。
#       機械向けの合図だけ**最後の1行に `<<WIP>>`**(作業が続いている時だけ)。
#   ★**Chamiの目には触れさせない。** `<<WORK>>` と同じ仕組みで送信前に取り除く
#     (Chamiの部屋に `<<WIP>>` の文字が出たら、それ自体が事故)。
#   ★正本= 全部門共通規律 §4.55(HQが2026-07-29に差し替え済み)。
WIP_MARKER = "<<WIP>>"
# ★★除去は**揺れを全部吸収する**(2026-07-29 04:09 実際にChamiの目に触れたため)。
#   Chami原文=「**<<WIP>>って何?余計な文字要らんよ**」(人事部門 msg=1531739722144022729)。
#   事故の構造= 規律(「最後に <<WIP>> を書け」)は**次の便から即効**なのに、
#     それを取り除くコードは**載せ替えに90秒かかる**。受け皿が無い時間帯が生まれ、
#     04:03:01 の hr-room の返信が生のまま出た(=§4.55の「どこに入れれば、いつから効くか」の表そのもの)。
#   → **一度Chamiに見せた文字は二度と出さない。** 完全一致だけでなく次を全部吸収する:
#     大文字小文字(`<<wip>>`)・全角の山括弧(`＜＜WIP＞＞`)・内部の空白(`<< W I P >>`)・
#     全角空白・前後の空白・強調やコードの飾りだけが残った行。
#   ★`<<WORK>>` には**この強化を及ぼさない**(回送の生命線。split_work_marker は1文字も変えていない)。
_WIP_RE = re.compile(r"[<＜]{2}[\s　]*W[\s　]*I[\s　]*P[\s　]*[>＞]{2}", re.IGNORECASE)
# 除去した後に「飾りだけ」になった行は丸ごと落とす(`**<<WIP>>**` → `****` を残さないため)
_WIP_DECOR = "*_`~-—–:：|>　 \t"


def split_wip_marker(reply):
    """返信本文から WIP_MARKER を取り除き (本文, 作業継続の申告) を返す。

    ★`split_work_marker` と**同じ作法**(行内のどこにあっても拾う・マーカーだけの行は丸ごと落とす)。
      違うのは**揺れの吸収を強めてある**点だけ(上の注記。実際に漏れた事故への対処)。
    ★`<<WORK>>` の扱いには**一切触らない**(回送の生命線。別の関数・別の定数のまま)。
    ★どんな入力でも例外を投げない(None/数値/dict でも空文字を返す)。
    """
    text = str(reply or "")
    if not _WIP_RE.search(text):
        return text.strip(), False
    kept = []
    for line in text.splitlines():
        if _WIP_RE.search(line):
            rest = _WIP_RE.sub("", line)
            # マーカーを抜いた跡に空白が2つ並ぶので詰める(「途中まで出来た  よ」を作らない)
            rest = re.sub(r"[ \t　]{2,}", " ", rest).strip()
            if rest.strip(_WIP_DECOR):      # 飾りだけになった行は落とす
                kept.append(rest)
        else:
            kept.append(line)
    return "\n".join(kept).strip(), True


# ★マーカー遵守率の監査(2026-07-20 組織層GL室・Chami「着手して」)
#   WORK_MARKERで発火はキャラの自己申告に一本化したが、申告を**書き漏らす**と従来どおり沈黙する
#   =事故の再発経路が1本だけ残る。しかも現状その頻度を誰も測っていない。
#   ★禁止事項との関係: 「キーワードを増やすな」は**入力(Chamiの依頼文)の分類**の話。
#     ここでやるのは**出力(キャラ自身の返信)の事後監査**なので別物。
#     入力の自然文は無限だが、「約束した」の表現はキャラ自身の語彙=有限で、しかも
#     外しても実害が回送ノイズで済む(判定の非対称性がある)。
#   ★語尾の揺れに注意。初版は「整理しておく」「出しておく」の〜ておく形だけを並べていたが、
#     実測の返信は「整理してそっちに出すぜ。少し待ってろ。」で**1語も一致しなかった**
#     (2026-07-20 hr-context・実弾で発見)。キャラは口語で約束するので〜ておく形に頼れない。
#   ★★コスト非対称の前提を訂正した(2026-07-20 21:10 実測):
#     当初「拾いすぎ=main箱へ余計な1件・実害なし」と書いたが**これは誤り**だった。
#     研究室が寝ている間は claude_responder(無人代打)がmain箱を処理して**Discordへ返信する**ため、
#     誤検出は「同じ部屋でChamiが2回返事をもらう」という**利用者に見える実害**になる。
#     実際に consult-intel で発生させた(下記)。よって再現率一辺倒では倒さず、
#     **「話者が自分の次の行動を宣言している形」だけを拾う**方針に変更する。
#   ★除外した語(descriptiveな地の文に出るため誤検出源だった):
#     「整理して」「まとめて」「調べる」「対応する」「回す」「組む」「進める」等の
#     **裸の辞書形/テ形**。実測の誤検出=consult-intel「受け取って整理してファイルに積んで満足、
#     は成果じゃないわ」(整理して に一致・**約束ではなく否定文の説明**)。
#     残すのは 〜ておく形・文末の意志表現(〜ぜ/〜わ/〜ます)・語彙的に一意な受諾語だけ。
PROMISE_WORDS = (
    # 受諾(語彙的に一意)
    "やっておく", "やっとく", "やるぜ", "やるわ", "やります", "引き受け", "受けた",
    "受け取った", "任せ", "承知",
    # 着手の表明
    "手をつける", "手を付ける", "着手する", "進めておく", "進めるわ", "進めるぜ",
    "対応しておく", "対応するわ", "対応するぜ",
    # 成果物を出す約束(意志の文末形のみ。「整理して」等のテ形は入れない)
    "出すぜ", "出すわ", "出します", "出しておく", "まとめておく", "整理しておく",
    "作っておく", "用意しておく", "組んでおく",
    # 調査の約束
    "見ておく", "調べておく", "調べるわ", "調べるぜ", "確認しておく",
    # 回送の約束(これを言って回さないのが元の事故)。裸の「回す」は説明文に出るので入れない
    "回すわ", "回します", "回しておく", "回すぜ", "回すね",
    # 「待ってろ」系=これから自分が動く合図(実測で最も頻出)
    "待ってろ", "待ってて", "待ってくれ", "少し待", "ちょっと待",
)
MARKER_AUDIT = os.path.join(LOCAL, "_marker_audit.jsonl")


def find_promise(reply):
    """返信本文が「自分がやる」と約束しているように読めるならその語を返す(無ければ None)。"""
    text = str(reply or "")
    for w in PROMISE_WORDS:
        if w in text:
            return w
    return None


def _match_context(reply, matched, span=40):
    """一致語の前後を切り出す(誤検出かどうかを人が判定するための証拠)。"""
    if not matched:
        return None
    text = str(reply or "")
    i = text.find(matched)
    if i < 0:
        return None
    return text[max(0, i - span):i + len(matched) + span]


def audit_marker(dept, rec, reply, declared, kw_work):
    """申告の遵守を事後計測し、書き漏らし便を救済すべきかを返す。

    記録する事象は2種類だけ(これで 取りこぼし率 = miss / (declared + miss) が出せる):
      - declared: キャラが申告した便(分母側)
      - miss    : **約束しているのに申告が無い**便(分子側)=旧実装なら沈黙していた便
    どちらでもない便(雑談・質問)は記録しない=台帳を膨らませない。

    戻り値: True なら救済(=is_workへ倒す)。約束の証拠はキャラ自身の返信の中にあるので、
    黙って落とさず回送する方へ倒す。
    ★ただし誤検出はタダではない(研究室が寝ていると無人代打が返信し**二重応答**になる)。
      PROMISE_WORDSの注記を参照。精度側の調整はこのログの miss を読んで行うこと。
    """
    promise = None if declared else find_promise(reply)
    if not declared and not promise:
        return False
    if declared:
        event, matched = "declared", None
    elif kw_work:
        # キーワードが既に拾っている=回送は起きるので沈黙事故ではない。分子には数えない
        event, matched = "miss_covered_by_keyword", promise
    else:
        event, matched = "miss", promise
    try:
        with open(MARKER_AUDIT, "a", encoding="utf-8") as f:
            f.write(json.dumps({
                "ts": time.strftime("%Y-%m-%dT%H:%M:%S"),
                "dept": dept,
                "event": event,
                "matched": matched,
                "msg_id": str(rec.get("msg_id", "")),
                "content": str(rec.get("content", ""))[:200],
                "reply": str(reply or "")[:200],
                # ★一致箇所の前後を必ず残す(2026-07-20 実測): reply[:200]の切り詰めで
                #   一致語そのものが切り落とされ、誤検出か正検出か判定できない便が出た
                #   (platform-se・'回す')。証拠が読めない監査ログは精度調整に使えない。
                "matched_context": _match_context(reply, matched),
            }, ensure_ascii=False) + "\n")
    except OSError:
        pass  # 監査は本番経路を壊さない(落ちても応答は続ける)
    return event == "miss"


# ============================================================================
# ★「待ちます」の自動解除(2026-07-29。find_promise/audit_marker の兄弟機構)
# ============================================================================
# Chami原文(2026-07-29):
#   「**ダウンロード完了の通知が来るまで待ちます。**」
#   「からこっちがまだ?っていうまで止まっていた。全部門でというかもうこういうのやめて欲しいんだよ。
#     何のためのオーケストレーションなの?って。自律的に動いてほしい。…何回言わすんだこれ…」
#
# ★構造(なぜ規律では止まらないか):
#   部門のセッションが「〜を待ちます」と書いてターンを終える。**だがその待ちを解除する者が誰も居ない。**
#   便が来ない限りセッションは動かない= **「待ちます」は事実上の永久停止**であり、
#   Chamiが「まだ?」と言うまで誰も気づかない。
#   共通規律§2に「待たせる相手が居ないなら、待たせてはいけない」と**既に書いてある**。
#   それでも起きた= **規律では止まらない。だから機構で止める。**
#
# ★やること= 待ちの宣言を見つけたら、**同じ部屋のキューへ追撃の便を1回だけ入れる**。
#   Discordへ機械が喋るのではない(2026-07-28の方針=機械が部屋で喋るな)。便を入れて
#   **セッション自身に考えさせる**。答えるのは人格であって機構ではない。
#
# ★誤検出はタダではない(PROMISE_WORDSの注記と同じ非対称性):
#   誤検出=Chamiの部屋に余計な便と余計な返信が出る=**Chamiの部屋を汚す**。
#   よって **迷ったら検出しない側へ倒す**。以下の3段構えで絞る:
#     (1) **意志の文末形だけ**を見る(文中の「判断待ち」「承認待ちボード」等の名詞は拾わない)
#     (2) その文に**相手が居る語**(Chami/承認/裁定/返事/GO…)があれば**除外**
#         = 「Chamiの返事を待ちます」は**正しい待ち**であって事故ではない
#     (3) 否定・過去形(待たず/待つ必要/待たされ…)を含む文は除外
#   ★実測(2026-07-29): 本番の返信 877件に流して検出2件・**誤検出0件**。
#     内訳= llm-edu「ダウンロード完了の通知が来るまで待ちます」(=Chamiが怒った実物)と
#           llm-edu「ComfyUIが上がったら進めます」(=どちらも解除する者が居ない本物の待ち)。
#     一方「待」を含む返信は123箇所あり、その121箇所は「判断待ちボード」「Chami裁定待ち」
#     「ちょっと待ってて」等= **拾ってはいけないもの**だった。文末形+相手語の除外で全部落ちている。

# (1) 意志の文末形。**文の末尾**にだけ一致させる(地の文の「〜待ちで止まってる」を拾わないため)。
WAIT_TAIL_RE = (
    re.compile(r"待ちます$"),
    re.compile(r"(お)?待ちしています$"),
    re.compile(r"(お)?待ちしてます$"),
    re.compile(r"お待ちします$"),
    re.compile(r"待機します$"),
    re.compile(r"待機しておきます$"),
    re.compile(r"待つことにします$"),
    re.compile(r"待ちたいと思います$"),
    # 「待つ」と書かずに待つ形= 条件が満たされたら動く宣言。その条件を誰も満たしに行かない。
    # 例「完了後に続けます」「結果が出たら報告します」。★条件語と動詞の間は読点を跨がせない
    #   (跨がせると別の文の断片と繋がって誤検出する)。
    re.compile(r"(たら|次第|完了後に|終わったら|来たら|出たら|届いたら|終わるまで|来るまで|終わり次第)"
               r"[^、]{0,25}?(進めます|続けます|再開します|報告します|着手します|"
               r"取り掛かります|取りかかります|開始します|やります)$"),
)
# (2) **相手が居る待ち**= 事故ではない。ここに一致したらその文は見なかったことにする。
#   ★Chamiの裁定・承認・返事を待つのは**正しい**(勝手に進む方が事故)。
WAIT_COUNTERPART = (
    "chami", "ちゃみ", "チャミ", "あんた", "あなた", "君", "お前", "きみ",
    "承認", "裁定", "許可", "返事", "返答", "指示", "判断", "回答", "返信",
    "go", "ゴー", "ok", "オーケー", "合図", "レビュー", "決裁", "連絡",
    # ★★2026-07-29 03:18 **本番で最初の誤検出が出たので足した**(実弾で見つけた1件)。
    #   実物= system-engineer「状態: 待ち(実機で貼付→反映の確認)」。
    #   直前の返信は「ちゃみが投稿モードを開き直して、URLの箱が出てるか見て」=
    #   **Chamiの目で実機を見てもらう待ち**= 相手が居る=正しい待ちだった。
    #   なのに括弧の中にChamiの名前が無いため、上の語では落ちなかった。
    #   → 「確認」「実機」「目視」「検収」を足す。**待ちの札の括弧に出る「確認」は、
    #     ほぼ必ず“人が見る”という意味**だから(機械の完了は「完了」「起動」「生成」と書かれる)。
    #   ★これで「ダウンロード完了の確認待ち」のような自分で確かめられる待ちも落ちるが、
    #     **迷ったら検出しない**(誤検出でChamiの部屋を汚す方が害が大きい)を優先する。
    "確認", "実機", "目視", "検収", "フィードバック",
)
# (3) 否定・過去形・地の文。「待たずに進めた」「待つ必要はない」を拾わない。
WAIT_NEGATIVE = ("待たず", "待たない", "待つ必要", "待たなくて", "待ちません",
                 "待たされ", "待たせ", "待っていた", "待ってた")
_WAIT_SENT_SPLIT = re.compile(r"[。！!？?\n]+")
# 文末の飾り(閉じ括弧・強調の**・箇条書きの記号)を落としてから文末判定する。
_WAIT_TAIL_TRIM = "　 \t)）」』】>*_-–—・~〜、,."

# 追撃までの待ち時間(秒)。★即座に撃たない理由= その瞬間はまだ本当に処理中かもしれない
#   (relayの1便は実測60〜200秒、作業便のhardは1200秒)。撃つのが早すぎると
#   「作業中の相手を急かす便」になり、これも部屋のノイズになる。
#   600秒(10分)= 作業便のhard(1200秒)の半分・relayの実測往復の3倍以上。
#   発注の目安5〜15分の中央を取った。★短くしたくなったら、まず実測(request_logのslow)を見ること。
WAITING_FOLLOWUP_SEC = 600
# 掃き出しの間隔(秒)。ループは2秒毎に回るので必ず間引く(台帳を毎秒読まない)。
WAITING_SWEEP_SEC = 60
# 台帳の読み取り上限(バイト)。request_log.jsonl は追記専用なので**末尾だけ**読む。
WAITING_LOG_TAIL = 2 * 1024 * 1024
# 追撃便の msg_id 接頭辞。★この接頭辞の便には**二度と追撃しない**(無限ループ禁止)。
WAITING_PREFIX = "WAIT-"

# ============================================================================
# ★「完了の自発報告が無い」問題(2026-07-29・上の待ちと**同じ構造**)
# ============================================================================
# Chami原文(2026-07-29):
#   「**いや、それはこっちが終わったか自発的に聞いたから報告があっただけであって、
#     向こうから終わったって自発的な報告がないのよ。**」
# 構造= セッションは**便が来た時しか動かない**。だから作業を始めて「まだ続いている」と返した後、
#   実際に作業が終わっても**知らせるきっかけが無い**。Chamiが「終わった?」と聞いて初めて出る。
#   = **完了の自発報告が構造的に存在しない。**「待ちます」と同じ穴なので同じ機構で塞ぐ。
#
# ★★合図は `<<WIP>>` の1形だけ(2026-07-29 **札を廃止して差し替えた**)。
#   最初の実装は共通規律§4.55の `状態: 作業中` という**札**を読んでいたが、Chamiが札そのものを
#   却下した=「**最後の状態:完了とかやめて欲しいなあ、文脈でわかるようにして欲しいってこと。**」
#   → 本文はChamiが読んで分かる普通の文章のまま。機械向けの合図だけ `<<WIP>>` の1行。
#     **送信前に取り除くので、Chamiの目には触れない**(WIP_MARKER / split_wip_marker を参照)。
#   ★札の読み取り(飾り許容・最後の札を採る)は**捨てた**。マーカーは1形しかないので揺れが無い。
#   ★これは検出の精度にも効く: 実測で唯一の誤検出は**札の読み取りが出したもの**だった
#     (2026-07-29 03:18 system-engineer「状態: 待ち(実機で貼付→反映の確認)」=
#      実際はChamiに実機を見てもらう待ちで、相手が居る=正しい待ちだった)。
#     明示マーカーは「書いた本人がそう申告した」以外の解釈が無いので、この種の誤読が起きない。
#
# ★遅延を「待ち」より長く取る理由(実測 2026-07-29・request_logのleased→completed 212便):
#     全便    中央値101秒 / p90 301秒 / p99 610秒 / 最大 672秒
#     作業便  中央値232秒 / p90 601秒 / 最大 672秒 (n=40)
#   1便が占有しうる上限は relay の hard=1200秒(20分)。「作業が続いている」はそもそも
#   **1便の中で終わらない作業**(ダウンロード・ビルド・生成)を指すので、
#   その上限を跨いだ上で余裕を取る。1800秒(30分)= hardの1.5倍・実測最大(11.2分)の2.7倍。
#   ★これより短いと「まだ本当にやっている相手」を急かす便になる(=部屋のノイズ)。
WORKING_FOLLOWUP_SEC = 1800
WORKING_PREFIX = "WORK-"

# ★★未完了の依頼の自走(2026-07-29。正本= 改善書_記憶と引き継ぎの抜本見直し §5 / §6 第1手)。
#
# 直す穴(改善書が数字で特定した主因):
#   > **記憶は継がれている。実行が継がれていない。**
#   実話= 07:13 Chami依頼 → 引き継ぎに「未着手」と**正しく**記載 → 11:29「できてないじゃないか」
#         → 12:07 機構が催促 → 部屋は「**どちらから行くか向きを教えてくれ**」と返し
#         → Chamiが答えず **12:07〜15:37 の3.5時間停止**(change_logの空白で実測)。
#   = **忘れていない。書いてある。誰も実行に変換していない。**
#     Chamiの再依頼が毎回「再開の合図」になっている。これがZ1(Chamiの手数)の正体。
#
# ★★新しい常駐は作らない= 既に在る掃き出し(sweep_waiting)へ**トリガーを1つ足すだけ**。
#   台帳も増やさない= request_log.jsonl に request_detected / request_followup で1行。
#   検出器も増やさない= 積むきっかけは既存の find_working()/find_waiting() の検出そのもの。
# ★遅延を「作業継続」と同じ 1800秒(30分)にした理由:
#   改善書§6 第1手の例示が「例: 30分」。かつ WORKING_FOLLOWUP_SEC と同値にしておけば、
#   「1便が占有しうる上限(relayのhard=1200秒)を跨いだ上で余裕を取る」という
#   既に実測で決めた根拠をそのまま流用できる(根拠を2本持たない)。
REQUEST_FOLLOWUP_SEC = 1800
# ★接頭辞は WAIT-/WORK- と別にする。台帳の id(REQ-…)とも混ざらないよう REQF-。
REQUEST_PREFIX = "REQF-"
# 台帳に生きた依頼が在っても、部屋がまだ動いていれば撃たない(=止まっている時だけ押す)。
REQUEST_STACK_SOURCE = "dept_daemon(その便の中で終わらなかった)"

# ============================================================================
# ★★C-046(2026-08-14 HQ裁定・種= イージス研究室)= 起票の引き金に「返信側の状態」を使うな
# ============================================================================
# HQが request_log.jsonl で1件を頭から追跡した実測(便 1537384908530393109):
#     Chami便「**直った**」 → 部門はちゃんと返信(discord_msg 1537388201839427604)
#     → **その返信に `<<WIP>>` が付いていた**(別件の作業継続) → working_detected
#     → **依頼を1つも含まない便が REQ として起票**され、最長12日 台帳に立っていた。
#     生きた REQ 143件のうち **17件が依頼ですらない**(「直った」「出た。OK!」「進捗は?」「まだ?」)。
# ★真因= **起票の中身は「元の便」なのに、引き金は「返信側の状態」**という非対称。
#   `<<WIP>>` は**閉じ忘れの検出器であって、依頼の検出器ではない。**
# ★直し方(受け入れ条件)=
#   ① 起票の判定は「**元の便に依頼が含まれるか**」で行う。返信側の状態は**追撃便の引き金だけ**に使う。
#   ② 起票する時に `close_when`(何が起きたら閉じるか)を1行持たせる。書けないなら起票しない。
#   ③ 催促(「まだ?」「進捗は?」)は**新規起票しない**。既存REQの再掲として待ち時間を更新する。
#      ★催促で件数が増える台帳は、遅い部門ほど数字が悪化する=**原因ではなく結果を測ってしまう**。
#   ④ 自動closeはしない(C-024据え置き)。
# ★★倒す向きは「起票する側」だ= 迷ったら request(取りこぼし0=イージス研究室のKPI A1)。
#   落とすのは**言い切れる形だけ**(催促・相槌・完了報告)。
_ASK_RE = re.compile(
    r"(して|しといて|しておいて|下さい|ください|お願い|頼む|頼み|やって|やろう"
    r"|直し|直せ|進めて|再開|着手|対応|作って|入れて|外して|消して|止めて|閉じ|開け"
    r"|やっといて|調べ|見て|見といて|確認して|教えて|出して|変えて|付けて|足して|試して|回して"
    r"|欲しい|ほしい|したい|できる[?？]|できます|任せ|よろしく|検討|実装|修正|追加)")
# 催促(=既存の依頼の再掲)。★「答えは返信そのもの」型(HQ ④)。
_NUDGE_RE = re.compile(
    r"(まだ|進捗|どうなった|どうなってる|どうなりました|遅い|いつまで|いつになったら"
    r"|何時間|時間経|経ってます|経ちました|終わった[?？]|終わってる[?？]|返事)")
# 完了報告・相槌。★これ**だけ**の便は依頼を含まない。
_DONE_RE = re.compile(
    r"(直った|直りました|治った|出た|出ました|出てる|出るように|できた|できてる|動いた"
    r"|反映され|表示され|うまくいっ|成功|問題ない|問題なし|大丈夫|解決|良さそう|いい感じ)")
_ACK_RE = re.compile(
    r"(ok|okay|おk|了解|承知|ありがとう|あざす|thx|thanks|なるほど|そうか|そうだね|はい"
    r"|うん|把握|お疲れ|おつかれ|おはよう|おやすみ)", re.I)
_ASK_TRIM_RE = re.compile(r"[\s。、,.!！?？…‥・~〜\-—:：;；\"'`()（）\[\]「」『』【】★☆♪笑w]+")
# 語尾だけの残りかす。★「残りかす」を数える時にだけ落とす(判定の合図には使わない)。
_ACK_TAIL_RE = re.compile(r"(ございます|でした|ですね|です|ました|ます|だね|だよ|みたい|そう"
                          r"|ので|から|けど|よかった|かな|わ|よ|ね|な|ぞ|ぜ)")
# 催促と見なす上限(字)。★長い便は「催促の後ろに実依頼が付いている」ことがある(HQ §4の実測)。
NUDGE_MAX_CHARS = 60
# 相槌と見なす残りかす(字)。★「OK。①割引が…」のような**相槌+実依頼**を落とさないための門。
#   実測で決めた= 「出たのでok」の残り「ので」=2字は落としたいが、「OK。①割引が」の
#   残り「①割引が」=4字は**落としてはいけない**(HQ §4=相槌の後ろに実依頼が付いている)。
ACK_RESIDUE_MAX = 3

CLOSE_WHEN_REQUEST = "頼まれた物の実物(変更したファイル/実行結果/Discordの返答便)を、その場面で確認できた時"
CLOSE_WHEN_QUESTION = "この問いへ返した返答便(discord_msg)を実物ポインタとして確認できた時"
CLOSE_WHEN_NUDGE = "催促が指す作業の実物を、Chamiが催促した場面で確認できた時"


def classify_ask(text):
    """**元の便の中身だけ**を見て種別を決める。戻り値 (種別, close_when)。

    種別= "request"(起票する) / "nudge"(既存へ寄せる) / "ack"(何もしない)。
    ★純粋関数(副作用なし)。判定はここ1箇所だけに置く=二重の判定を作らない(ORG-11)。
    """
    t = " ".join(str(text or "").split())
    if not t:
        return "ack", ""
    if _ASK_RE.search(t):                       # ①依頼の合図が在れば、他に何が書いてあっても起票
        return "request", (CLOSE_WHEN_QUESTION if t.rstrip().endswith(("?", "？"))
                           else CLOSE_WHEN_REQUEST)
    if _NUDGE_RE.search(t) and len(t) <= NUDGE_MAX_CHARS:
        return "nudge", CLOSE_WHEN_NUDGE        # ②催促だけ(短い便に限る)
    residue = _ASK_TRIM_RE.sub("", _NUDGE_RE.sub("", _ACK_RE.sub("", _DONE_RE.sub("", t))))
    residue = _ASK_TRIM_RE.sub("", _ACK_TAIL_RE.sub("", residue))
    if (_DONE_RE.search(t) or _ACK_RE.search(t)) and len(residue) <= ACK_RESIDUE_MAX:
        return "ack", ""                        # ③相槌・完了報告だけ(残りかすが無い時だけ)
    return "request", (CLOSE_WHEN_QUESTION if t.rstrip().endswith(("?", "？"))
                       else CLOSE_WHEN_REQUEST)  # ④既定は起票(取りこぼしを作らない)


def request_followup_text(items, quiet_sec):
    """暇な部屋への催促(★改善書§6 第1手の文面指定=「上から順に進めろ。向きを聞くな」)。

    items= session_relay.open_request_list() の戻り(未完了の依頼)。
    ★禁じるのは「**着手の順番を聞いて止まること**」であって、Chamiへ問い返すこと自体ではない。
      外したら作り直しになる1点なら聞いてよい(共通規律§4.55の趣旨)。ここを取り違えさせない。
    """
    lines = []
    for i, d in enumerate(items[:10], 1):
        sym = " ".join(str(d.get("symptom") or "").split())[:140]
        lines.append(f"  {i}. [{d.get('id','')}] {sym or '(依頼の本文なし。元の便を見ること)'}")
        lines.append(f"     依頼の便の在りか= {d.get('broken') or '(無い★)'}"
                     f" / 頼まれた= {d.get('noticed_at') or '不明'}")
    more = ("" if len(items) <= 10 else f"  …ほか {len(items) - 10}件\n")
    return (
        "【未完了の依頼の自動催促・機構からの追撃(2026-07-29 改善書 第1手)】\n"
        f"この部屋は **{int(quiet_sec // 60)}分**どの便も受けていない。"
        "だが**Chamiが頼んだまま終わっていない依頼**が機械の台帳に残っている:\n"
        + "\n".join(lines) + "\n" + more +
        "\n"
        "★★**上から順に進めろ。向きを聞くな。**\n"
        "  『AとBのどちらから行きますか』と聞いてターンを終えるな。"
        "**あなたは便が来た時しか動かない**ので、Chamiが答えるまでこの部屋は止まる。\n"
        "  実測(2026-07-29): まさにそれで **12:07→15:37 の3.5時間**この部屋は停止した。"
        "その間Chamiは2回言い直している。\n"
        "★既定の順番= **この一覧の一番上から**。Chamiが『〜を先に』と言った時だけ入れ替える。\n"
        "★**問い返し自体は禁じていない。**"
        "外したら作り直しになる1点(仕様の分岐・消してよいデータ等)なら聞いてよい"
        "(共通規律§4.55の趣旨)。禁じているのは**着手の順番を聞いて止まること**だ。"
        "順番は外しても作り直しにならない。\n"
        "★進められない依頼が在るなら、**何が揃えば進むかを1行**で書いて、次へ行け"
        "(止まるな。1件で詰まっても他は進む)。\n"
        "★**閉じ方は不具合と同じ厳しさだ。**『やりました』では台帳から消えない。"
        "終わった実物の在りか(Discordのmsg_id/リンク・実在するファイルのパス・URL)と"
        "『どの場面で確かめたか』を添えて、**生JSONを手打ちせず**次を実行しろ"
        "(★2026-08-12・手打ちの `\\` で行が壊れ、confirmが黙って消えた実話がある):\n"
        '   python scripts/llm/close_item.py --id <上のID> --dept <部屋> '
        '--fixed "<終わった実物の在りか>" --scene "<どの場面で確かめたか>" --by "<誰>"\n'
        "  (中身は台帳への1行追記。受理/不受理はその場で表示される)\n"
        "★**commitのhashだけでは受理されない。**")


def find_working(reply, wip=False):
    """作業が続いている申告(`<<WIP>>`)があれば証拠の文字列を返す(無ければ None)。

    ★判定は**マーカー1形だけ**。本文のテキストからは推測しない
      (「作業中です」等の言い回しを拾う案は実測で 0件=再現ゼロ、
       `find_promise()` で代用する案は 891件中149件=16.7%が発火して部屋を溢れさせる。
       中間が無いので**書いた本人の申告だけを信じる**方へ倒した)。
    ★`wip` は `split_wip_marker()` が返した申告。**本文からマーカーを落とした後**に
      呼ばれる経路があるため、フラグで受け取れるようにしてある(落とす前の本文を渡してもよい)。
    """
    if wip:
        return WIP_MARKER
    if _WIP_RE.search(str(reply or "")):
        return WIP_MARKER
    return None


def find_waiting(reply):
    """返信が「(解除する者の居ない)待ち」を宣言しているなら、その一文の末尾を返す(無ければ None)。

    ★find_promise() と同じ作法: 地の文を拾わない・**意志の文末形**だけを見る。
    ★判断がつかない時は**検出しない側**へ倒す(誤検出でうるさくする方が害が大きい)。

    ★★2026-07-29 **状態札の読み取りを外した**(Chamiが札そのものを廃止したため)。
      ここは `<<WIP>>` のような明示マーカーへは寄せず、**本文のテキスト判定のまま**にした。
      決めた理由(実測):
        - 待ちを表すマーカーは規律に**存在しない**(HQが入れたのは `<<WIP>>` 1つだけ)。
          誰も書かないマーカーを見に行っても**一度も発火しない**=機構として無意味。
        - テキスト判定の実測は良い= 本番の返信 892件で検出2件・**誤検出0件**。
          検出した2件はどちらも本物(「ダウンロード完了の通知が来るまで待ちます」
          「ComfyUIが上がったら進めます」= どちらも解除する者が居ない)。
        - 唯一の本番誤検出(2026-07-29 03:18 system-engineer)は**札の読み取りが出したもの**で、
          テキスト判定が出したものではない。**その札の経路は今回まるごと消える。**
      ★つまり「誤検出を出した側だけを外し、0%の側を残す」= 迷わず残す判断ができた。
    """
    text = str(reply or "")
    if not text:
        return None
    for raw in _WAIT_SENT_SPLIT.split(text):
        s = raw.strip()
        if not s:
            continue
        low = s.lower()
        if any(w in low for w in WAIT_COUNTERPART):
            continue                      # 相手が居る待ち=正しい待ち
        if any(w in s for w in WAIT_NEGATIVE):
            continue                      # 否定・過去形・地の文
        t = s.rstrip(_WAIT_TAIL_TRIM)
        if not t:
            continue
        for rx in WAIT_TAIL_RE:
            if rx.search(t):
                return t[-40:]            # 証拠として一文の末尾40字だけ残す
    return None


def waiting_followup_text(matched):
    """追撃便の本文(★機械の説教ではなく、**自分で確かめに行け**という指示)。"""
    return (
        "【待ちの自動解除・機構からの追撃(2026-07-29 Chami指示)】\n"
        f"さっきあなたは「{matched}」と書いてターンを終えた。\n"
        "★だが、**その待ちを解除する者は居ない。** 便が来ない限りこの部屋は止まったままだ。\n"
        "Chamiが「まだ?」と言うまで誰も気づかない= それは事実上の永久停止だ。\n"
        "\n"
        "次のどれかを、今この場でやること:\n"
        "① **自分で確かめに行け。** ファイル・ログ・コマンド・APIで**実物を見る**"
        "(存在するか・サイズは・プロセスは上がっているか)。人からの報告を待たない。\n"
        "② 確かめられないなら、**待たずに進められる所まで進め。** 待ちに依存しない作業は必ず在る。\n"
        "③ 本当に進めないなら、**何が揃えば進むのかを1行で書け**(Chamiが動けるように・"
        "「誰が」「何を」すれば解けるのかを具体的に)。\n"
        "\n"
        "★もう一度「待ちます」と書くな。"
    )


def working_followup_text(_matched=None):
    """作業が続いている便への追撃(★完了の**自発報告**を出させる。Chami 2026-07-29)。

    ★文面に札(`状態: 完了` 等)を書かせない= Chamiが札そのものを廃止したため
      (「文脈でわかるようにして欲しい」)。機械向けの合図は `<<WIP>>` の1行だけ。
    """
    # ★★文面に「合図をこう書け」を**書かない**(2026-07-29 04:15)。
    #   理由= 合図の書き方の正本は**共通規律§4.55**であって、この追撃便ではない(ORG-11=
    #   同じ規則を2箇所に置かない)。実際この直後にHQが「`<<WIP>>` を書くな」へ規律を差し替えており、
    #   もし文面に書き方を焼き込んでいたら、**機構が規律に逆らう指示を出す**ことになっていた。
    #   → 催促は「**終わったなら自分から報告しろ**」の1点に絞る。合図は規律に従わせる。
    return (
        "【完了報告の自動催促・機構からの追撃(2026-07-29 Chami指示)】\n"
        "さっきの返信であなたは**まだ作業が続いている**と申告して終えた。**あれは終わったか?**\n"
        "★あなたは**便が来た時しか動かない**。だから作業が終わっても、\n"
        "  自分から知らせるきっかけが無い= **Chamiが「終わった?」と聞くまで報告が出ない。**\n"
        "  Chami原文=「**向こうから終わったって自発的な報告がないのよ。**」\n"
        "\n"
        "次のどれかを、今この場でやること:\n"
        "① 終わっているなら、**Chamiへ自分から報告しろ。** 何をどこまでやったかを"
        "**普通の文章で**書く(★札は貼るな。Chami=『**文脈でわかるようにして欲しい**』)。\n"
        "  ★ただし §4.55 を守れ= **実物を見ていないなら「直った」と書くな。**"
        "「入れた(確認待ち)」なら**そう書く**(嘘の完了報告は、報告が無いことより悪い)。\n"
        "② まだなら、**今どこまで進んで、あと何が残っているか**を1行で書け。\n"
        "③ 詰まっているなら、**何が揃えば進むか**を書け(誰が何をすれば解けるのかを具体的に)。\n"
        "\n"
        "★機械向けの合図を付けるかどうかは**全部門共通規律§4.55の今の記述に従え**"
        "(この便では指示しない。規律が正本だ)。\n"
        "★Chamiは**この報告が無いせいで次の依頼を乗せられない。** 黙って続けるな。"
    )


