def common_discipline():
    """全部門共通の規律を**都度読み**して返す(2026-07-21 Chami指示)。

    Chami原文=「どこかで問題が起きたら**全部が勝手に自動的に更新されて、どの部門でも
    二度と起きない**仕組みにして。**こっちの承認とか、こっちが言わなくても裏で自動でやって**。
    じゃないとここで潰しても他の部門でまたやらかすやん」。

    ★なぜファイルを都度読みするのか(定数に埋めない理由):
      DEPT_CONFやモジュール定数は**プロセス起動時にしか読まれない**ので、教訓を1行足すたびに
      艦隊16部門の再起動が要る=運用が回らず、結局誰も足さなくなる(=今までがそれ)。
      mtimeを見て変わった時だけ読み直せば、**1行足した次の発話から全部門に効く**。
      registry_purpose() と同じ設計。

    ★これが無かった時に何が起きていたか: 教訓は台帳(インシデント.md)に書かれるだけで、
      **誰かが手で共通プロンプトへ移した分しか効かなかった**。移し忘れれば他部門が同じ穴を踏む。
      実際 ORG-08(人格)・ORG-13(URL)は「1箇所に書いただけ」で全部門に届いていなかった。

    読めなければ空文字(=規律が無くても応対は続ける。fail-open)。
    """
    try:
        m = os.path.getmtime(_DISCIPLINE)
        if m != _disc_cache["mtime"]:
            with open(_DISCIPLINE, encoding="utf-8", errors="replace") as f:
                _disc_cache["text"] = f.read().strip()
            _disc_cache["mtime"] = m
    except Exception:
        return ""
    return _disc_cache["text"]



def _disc_block():
    """共通規律をプロンプト用の節にする。空(読めない)なら何も足さない=fail-open。"""
    d = common_discipline()
    head = ("■全部門共通の規律(★必ず守る。違反は事故になる)\n" + d + "\n\n") if d else ""
    # ★裁定カタログの見出しも同じ経路で送る(2026-07-28)。注入口を2つ作らない=ORG-11。
    #   規律§3.7は「正本を読め」と書いてあるだけで、**実際には読まれていなかった**(実測)。
    try:
        return head + _verdict_block()
    except Exception:
        return head          # fail-open: 裁定が読めなくても規律は届ける


_verdict_cache = {"mtime": None, "text": ""}
_VERDICT_MD = os.path.join(HQ, "裁定カタログ.md")


def _verdict_block():
    """裁定カタログの**見出しと発注先の表だけ**を毎便同送する(2026-07-28)。

    ★なぜ要るか(実測):
      共通規律§3.7は「正本= 裁定カタログ.md。**中身はここに写さない**(読め)」と書いてあった。
      だが**カタログ自体は封筒に入っていない**ので、実際には読まれない。
      実害= C-015(発注先の表)を 07-27 11:59 に足したのに、07-28 01:47 にローカルllm教育部門が
      「**system-engineerさんへ回す形になります**」と答えた。★改修αは5秒動画専用=部門違い。
      Chami=「**seに回す考えが変わっていないなど、全部門に方針の統一みたいなのができてない**」。
      → **「読め」と書いてあるだけのものは読まれない。** 見出しだけでも毎便渡す。

    ★全文は入れない(封筒が肥大して、肝心の便が埋もれる)。
      入れるのは **①各裁定の見出し ②C-015の発注先の表**だけ。
      詳細が要る時は正本を読ませる(パスも一緒に渡す)。
    ★mtimeキャッシュ=Chamiが1行足した次の便から効く。読めなければ静かに諦める(fail-open)。
    """
    try:
        m = os.path.getmtime(_VERDICT_MD)
    except OSError:
        return ""
    if m != _verdict_cache["mtime"]:
        try:
            with open(_VERDICT_MD, encoding="utf-8") as f:
                raw = f.read()
        except OSError:
            return _verdict_cache["text"]
        # ★書式が2通りある(実測): C-001〜C-014は**表の行**、C-015以降は `### 見出し`。
        #   片方だけ拾うと**14件が丸ごと届かない**(最初の実装がそうだった)。両方拾う。
        heads = []
        for ln in raw.split("\n"):
            if ln.startswith("### C-"):
                heads.append(ln.strip().lstrip("#").strip())
                continue
            mm = re.match(r"^\|\s*\*\*(C-\d{3})\*\*\s*\|\s*(.+?)\s*\|", ln)
            if mm:
                title = re.sub(r"\*\*|★", "", mm.group(2)).strip()
                heads.append(f"{mm.group(1)} {title[:70]}")
        # C-015 の表(発注先)だけは行ごと渡す= 毎日使う判断なので見出しでは足りない
        table = []
        grab = False
        for ln in raw.split("\n"):
            if ln.startswith("### C-015"):
                grab = True
                continue
            if grab:
                if ln.startswith("### "):
                    break
                if ln.startswith("|"):
                    table.append(ln.rstrip())
        parts = []
        if heads:
            parts.append("■Chamiが既に下した裁定(★該当したら『判断』ではなく『執行』。"
                         "正本= 00_AI-HQ/裁定カタログ.md ・詳細はそこを読め)\n"
                         + "\n".join("- " + h for h in heads))
        if table:
            parts.append("★発注先(C-015・毎日使うのでここに全文を置く)\n" + "\n".join(table)
                         + "\n★改修α(system-engineer)は**5秒動画メーカー専用**だ。"
                           "組織の仕組み・人格・常駐構成を持ち込むな。")
        _verdict_cache["text"] = ("\n\n".join(parts) + "\n\n") if parts else ""
        _verdict_cache["mtime"] = m
    return _verdict_cache["text"]


def registry_purpose(dept):
    """org_registry.yml から purpose/kpi を**都度読み**する(2026-07-20 Chami指示への対応)。

    なぜDEPT_CONF(このファイル)ではなく台帳から読むのか:
      DEPT_CONFはモジュール定数=**プロセス起動時にしか読まれない**。目的やKPIはChamiが
      壁打ちしながら育てていく前提なので、追記のたびに艦隊再起動が要るのでは運用が回らない
      (characterfileを毎回読み直しているのと同じ理由)。台帳を正本にして都度読みにすれば、
      **Chamiがyamlへ1行足した次の発話から効く**。
    mtimeが変わった時だけ読み直すので、便ごとのYAMLパースは発生しない。
    読めなければ静かに諦めてDEPT_CONF側へフォールバックする(目的が無くても応対は続けるべき)。
    """
    try:
        m = os.path.getmtime(_REGISTRY)
        if m != _reg_cache["mtime"]:
            import yaml
            with open(_REGISTRY, encoding="utf-8") as f:
                _reg_cache["depts"] = (yaml.safe_load(f) or {}).get("depts") or {}
            _reg_cache["mtime"] = m
    except Exception:
        return None, None
    d = _reg_cache["depts"].get(dept) or {}
    return d.get("purpose"), d.get("kpi")


