    # ★設計の要点:
    #   - "personas"= 多人格モード。**誰として答えるかはセッション本人が選ぶ**(判定を外部へ出さない)。
    #     返信1行目の `[名前]` を handle() が読んで名義に反映する(split_persona_blocks/resolve_persona_tag)。
    #   - "members" は**置かない**。名指し(member_call)はrelayを迂回して精霊の会話へ落とす仕組みなので、
    #     多人格モードと衝突する(名前で呼ばれた時もセッション本人に選ばせたい)。
    #   - "conversation_only"= 回送しない・作業判定もしない。**その場で答え切る**部屋。
    #   ★人選の根拠= Chamiが「内容によっていろんな人に意見を求めたい」と言ったので**観点が割れる**顔ぶれ。
    #     ★past-room は **Chami本人が名簿を出した**(2026-07-26)のでそちらが正本。
    #       原文=「ククール / ミカヤ / ヴィルシーナ(講師兼任) / ジェンティルドンナ(QA兼任) /
    #       スネーク(QA兼任) / オタコン(QA兼任) / 黒川あかね(記録) / アメス(補佐)」
    #       「**基本アメスが答える形でも問題ない、まかせる。まだ人格がちゃんと入ってない人間は
    #       話さなくていい**」
    #       → **ミカヤ**(characterfileも原典も無い)/ **スネーク**(原典はあるがcharacterfileが無い)は
    #         この一言に該当するので **personas に入れない**。名簿に無い人も足さない。
    #     ★future-room は名簿がChamiから出ていないので発注どおりの顔ぶれ
